//go:build wasm

// web/client.go — WebAssembly entry point for this module.
// Auto-generated by webtyp when this file does not exist.
// Compiled to web/public/client.wasm and served on port 8080.
//
// DOM access: use webtyp.com/dom — https://pkg.go.dev/webtyp.com/dom
// Element constructors: use webtyp.com/html — https://pkg.go.dev/webtyp.com/html
// Do NOT use syscall/js directly; webtyp/dom wraps it with a builder API.
//
// UI ecosystem packages:
//   webtyp.com/css   — typed CSS DSL and design tokens
//   webtyp.com/svg   — SVG icon sprite API (typed, zero-typo icons)
//   webtyp.com/image — image HTML builders + WebP optimization pipeline
//   webtyp.com/js    — typed layer for Service Workers and Web Workers
//   webtyp.com/form  — form generation from Go structs (zero reflection, uses fmt.Fielder)
//
// To run/compile this project install the WebTyp CLI and launch it:
//   Linux/macOS: curl -fsSL https://raw.githubusercontent.com/webtyp/installer/main/scripts/install.sh | bash
//   Windows:     irm https://raw.githubusercontent.com/webtyp/installer/main/scripts/install.ps1 | iex
//   webtyp   # scaffolds project, dev server :8080, TUI, Chrome auto-reload, MCP :8080
//
// Compilation modes (L/M/S) are managed by webtyp — https://pkg.go.dev/webtyp.com/app
// For M and S modes (TinyGo): avoid all Go stdlib — use webtyp/* replacements (see table above).

package main

import (
	. "webtyp.com/dom"  // https://pkg.go.dev/webtyp.com/dom
	. "webtyp.com/fmt"  // https://pkg.go.dev/webtyp.com/fmt
	. "webtyp.com/html" // https://pkg.go.dev/webtyp.com/html
)

// App holds application state. Embed Element as a value (never pointer) to
// minimize heap allocations in TinyGo's GC.
type App struct {
	Element
	clicks int
	count  *SignalString
}

func (a *App) Init(_ Ctx) {
	a.count = NewString("0")
}

func (a *App) Render() *Element {
	return Div().Child(
		H1().Text("Hello from webtyp!"),
		Button().Text("Click me").Class("btn").On("click", func(e Event) {
			a.clicks++
			a.count.Set(Sprint(a.clicks)) // signal update patches only the text node
		}),
		P().Child(
			NewElement("span").Text("Clicks: "),
			NewElement("span").BindText(a.count),
		),
	)
}

func main() {
	// Inline CSS is fine for prototyping, but in a real component move styles to
	// ssr.go (//go:build !wasm) embedded with //go:embed — keeps them out of the
	// WASM binary. See: https://pkg.go.dev/webtyp.com/components
	Append("head", Style().Text(`
		.btn { padding: .4rem 1rem; cursor: pointer; border: none; border-radius: 4px; background: #007bff; color: white; }
	`))

	Render("app", &App{})

	// select{} keeps the WASM goroutine alive so JS event callbacks keep working.
	select {}
}
